$function splice(str,from,length){
    return str.substring(0, parseInt(from)) + str.substring(parseInt(from) + length, str.length);
}

function getImgList(){
    var p1 = "<script>window.*?=(.*?)<\/script>";
    var p = "data:\\s*'(.*)?',";
    var p2 = "\\d+[a-zA-Z]+";

    var str = html.match(p)[1];

    var nonce = eval(html.match(p1)[1]);
    var matches = nonce.match(new RegExp(p2,'g'));

    var len = matches.length;
    while ((len--) != 0) {
        var from = matches[len].match("^\\d+") & 255;
        var le = matches[len].replace(new RegExp("\\d+","gm"),"").length

        str = splice(str,from,le);
    }

    var json = eval("("+window.atob(str)+")").picture;

    var piclist = new Array([json.length]);
    for (var i = 0; i < json.length; i++) {
        piclist[i] = json[i].url;
    }

    return piclist;
};

